<template>
  <section class="workspace-panel">
    <div class="section-heading"><div><h2>Controlled Actions</h2><p>提案、审批与执行彼此分离。所有变更均以后端授权和状态检查为准。</p></div><button class="secondary-button" @click="showCreate=!showCreate">创建提案</button></div>
    <form v-if="showCreate" class="form-panel compact-form" @submit.prevent="createProposal"><div class="form-grid"><label>PolicyDecision ID<input v-model="decisionId" required /></label><label>目标 TrainingSession ID<input v-model="sessionId" required /></label><label>动作类型<select v-model="actionType"><option value="training_focus_override">training_focus_override</option><option value="difficulty_step_adjustment">difficulty_step_adjustment</option></select></label></div><button class="primary-button" :disabled="saving">提交受控提案</button></form>
    <AsyncState :loading="loading" :error="error" :empty="proposals.length===0" empty-title="暂无受控提案" empty-text="只有满足后端资格与治理门控的 Policy 决策才能创建提案。" @retry="load">
      <div class="proposal-list"><article v-for="proposal in proposals" :key="proposal.id" class="surface-card"><div class="section-heading"><div><small>{{ proposal.action_type }}</small><h3>{{ proposal.id }}</h3></div><StatusBadge :status="proposal.status" /></div><div class="panel-grid two"><div><h4>当前值</h4><JsonDetails :value="proposal.current_value" /></div><div><h4>建议值</h4><JsonDetails :value="proposal.proposed_value" /></div></div><p>目标训练：{{ proposal.target_training_session_id }}</p><p>有效期：{{ formatDateTime(proposal.expires_at) }}</p><div class="reason-list"><span v-for="code in proposal.reason_codes" :key="code"><strong>{{ explainReasonCode(code) }}</strong><code>{{ code }}</code></span></div><div class="action-row"><button v-if="proposal.status==='pending_review'" class="secondary-button" @click="ask('approve',proposal)">批准</button><button v-if="proposal.status==='pending_review'" class="secondary-button" @click="ask('reject',proposal)">拒绝</button><button v-if="proposal.status==='approved'" class="primary-button" :disabled="isSuspended(proposal)" @click="ask('apply',proposal)">确认应用到本次训练</button><button v-if="proposal.status==='applied'&&proposal.execution_id" class="secondary-button danger" @click="ask('rollback',proposal)">回滚</button></div><p v-if="isSuspended(proposal)" class="inline-notice danger">当前该类型受控操作已暂停，不能执行。</p></article></div>
      <article v-if="history" class="surface-card"><h3>操作审计与汇总</h3><JsonDetails :value="history.analytics" /></article>
    </AsyncState>
    <form class="form-panel compact-form" @submit.prevent="submitObservation"><h3>执行后观察与回滚</h3><div class="form-grid"><label>Execution ID<input v-model="executionId" required /></label><label>观察结果<select v-model="outcome"><option value="session_completed">session completed</option><option value="session_abandoned">session abandoned</option><option value="therapist_accepted">therapist accepted</option><option value="rollback_requested">rollback requested</option></select></label></div><label>备注<textarea v-model="comment" /></label><div class="action-row"><button class="secondary-button" :disabled="saving">保存观察</button><button class="secondary-button danger" type="button" :disabled="saving||!executionId" @click="rollbackManualOpen=true">回滚该执行</button></div></form>
    <ConfirmDialog :open="Boolean(pending)" :title="dialogTitle" :message="dialogMessage" :confirm-label="dialogLabel" :danger="pending?.kind==='apply'||pending?.kind==='rollback'" :busy="saving" @cancel="pending=null" @confirm="perform" />
    <ConfirmDialog :open="rollbackManualOpen" title="回滚已执行变更？" message="后端会校验当前状态并恢复该 execution 记录的执行前字段，不会覆盖后续人工修改。" confirm-label="确认回滚" danger :busy="saving" @cancel="rollbackManualOpen=false" @confirm="rollbackManual" />
    <p v-if="notice" class="inline-notice" role="status">{{ notice }}</p>
  </section>
</template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { controlledPolicyApi } from '@/api/controlledPolicy'; import AsyncState from '@/components/common/AsyncState.vue'; import ConfirmDialog from '@/components/common/ConfirmDialog.vue'; import JsonDetails from '@/components/common/JsonDetails.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { formatDateTime } from '@/utils/date'; import { explainReasonCode } from '@/utils/reasonCodes'; import type { ControlledHistory,ControlledProposal } from '@/types/professional'
const props=defineProps<{patientId:string}>(); type Action='approve'|'reject'|'apply'|'rollback'; const proposals=ref<ControlledProposal[]>([]),history=ref<ControlledHistory|null>(null),loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),showCreate=ref(false),decisionId=ref(''),sessionId=ref(''),actionType=ref<ControlledProposal['action_type']>('training_focus_override'),executionId=ref(''),outcome=ref('session_completed'),comment=ref(''),pending=ref<{kind:Action;proposal:ControlledProposal}|null>(null),rollbackManualOpen=ref(false)
const dialogTitle=computed(()=>({approve:'批准提案？',reject:'拒绝提案？',apply:'应用受控变更？',rollback:'回滚已执行变更？'} as Record<Action,string>)[pending.value?.kind||'approve']); const dialogLabel=computed(()=>pending.value?.kind==='apply'?'确认应用到本次训练':pending.value?.kind==='rollback'?'确认回滚':'确认'); const dialogMessage=computed(()=>pending.value?.kind==='approve'?'批准后仍不会自动执行，需要显式 Apply。':pending.value?.kind==='apply'?`将对训练 ${pending.value.proposal.target_training_session_id} 应用 ${pending.value.proposal.action_type}。后端会再次检查状态冲突与治理暂停。`:pending.value?.kind==='rollback'?'将恢复后端记录的执行前字段。':'拒绝会保留审计记录，不会执行变更。')
function isSuspended(p:ControlledProposal){return p.status==='suspended'||p.reason_codes.some(c=>c.toLowerCase().includes('suspend'))} function ask(kind:Action,proposal:ControlledProposal){pending.value={kind,proposal}}
async function load(){loading.value=true;error.value='';try{[proposals.value,history.value]=await Promise.all([controlledPolicyApi.proposals(props.patientId),controlledPolicyApi.history(props.patientId)])}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function createProposal(){saving.value=true;try{await controlledPolicyApi.create(props.patientId,decisionId.value,{action_type:actionType.value,target_training_session_id:sessionId.value});notice.value='提案已创建，等待显式审批。';showCreate.value=false;await load()}catch(e){error.value=msg(e)}finally{saving.value=false}}
async function perform(){if(!pending.value)return;const {kind,proposal}=pending.value;saving.value=true;try{if(kind==='approve')await controlledPolicyApi.approve(props.patientId,proposal.id,comment.value);if(kind==='reject')await controlledPolicyApi.reject(props.patientId,proposal.id,'therapist_rejected',comment.value);if(kind==='apply')await controlledPolicyApi.apply(props.patientId,proposal.id);if(kind==='rollback'&&proposal.execution_id)await controlledPolicyApi.rollback(props.patientId,proposal.execution_id,'therapist_rollback',comment.value);notice.value='后端已确认操作完成。';pending.value=null;await load()}catch(e){const m=msg(e);error.value=m.toLowerCase().includes('conflict')||m.includes('状态')?'训练状态已发生变化，本提案不会覆盖新的人工修改。请重新检查后创建新提案。':m}finally{saving.value=false}}
async function submitObservation(){saving.value=true;try{await controlledPolicyApi.observe(props.patientId,executionId.value,outcome.value,comment.value);notice.value='观察记录已保存。'}catch(e){error.value=msg(e)}finally{saving.value=false}} function msg(e:unknown){return e instanceof Error?e.message:'操作失败'} onMounted(load)
async function rollbackManual(){saving.value=true;try{await controlledPolicyApi.rollback(props.patientId,executionId.value,'therapist_rollback',comment.value);rollbackManualOpen.value=false;notice.value='后端已确认回滚。';await load()}catch(e){error.value=msg(e)}finally{saving.value=false}}
</script>
